// Individual component viewer: one ft electrical part, rendered from its
// precise FreeCAD B-rep.
//
// public/components/<id>.glb and components.json are GENERATED by
// stf-cad/hbw/components_cad.py from the parameter table components.py. The
// same table builds the .FCStd/.step files, so this view, the CAD file and the
// Gemini prompt cannot disagree. The mesh is tessellated at 0.01 mm chordal
// tolerance, and every housing is checked against its datasheet envelope to
// 0.01 mm before anything is written - the "Accuracy check" panel shows that
// check, it is not decoration.

import { Bounds, ContactShadows, Environment, Html, Lightformer, OrbitControls } from "@react-three/drei";
import { Canvas } from "@react-three/fiber";
import { Suspense, useEffect, useMemo, useState } from "react";
import * as THREE from "three";
import { ErrorBoundary } from "../shared/ErrorBoundary";

import { BASE, Src, ComponentDoc } from "./componentModel";
import { Actuator, Part, DimLine } from "./ComponentPart";

import { SwitchState, ValveState, PumpState, CylinderState, MotorState, TrackState } from "./ComponentStates";

const SRC_LABEL: Record<Src, string> = {
  datasheet: "datasheet", photo: "photo", "ft-std": "ft std", assumed: "measure", booklet: "booklet", model: "model",
};

export function ComponentView({ id, doc }: { id: string; doc: ComponentDoc }) {
  const c = doc.components[id];
  const [picked, setPicked] = useState<string | null>(null);
  const [showDims, setShowDims] = useState(true);
  const [wire, setWire] = useState(false);
  const [spin, setSpin] = useState(false);
  // Operable components. The mini switch's actuator stands 2.5 mm proud; pressed,
  // it goes down 2.0 mm (travel not in the datasheet - assumed, like btn_h).
  const actuator: Actuator | null = useMemo(
    () => (id === "mini_switch" ? { part: "actuator", travelMm: 2.0 } : null),
    [id],
  );
  const [on, setOn] = useState(false);
  useEffect(() => setOn(false), [id]);
  const motion = c.motion ?? [];
  const operable = !!actuator || motion.length > 0;
  const [xray, setXray] = useState(false);
  useEffect(() => setXray(!!c.xray), [id, c.xray]);
  // IR track sensor: where the black track is, mm along the housing (x)
  const [track, setTrack] = useState(9);
  const isIr = id === "ir_track_sensor";
  const [filter, setFilter] = useState<Src | "all">("all");
  useEffect(() => setPicked(null), [id]);

  const g = (k: string) => c.dims.find((d) => d.key === k)?.value ?? 0;
  const [L, W, H] = [g("L"), g("W"), g("H")];
  const f = (v: number) => `${v.toFixed(2)} mm`;
  const part = c.parts.find((p) => p.name === picked);
  const allOk = c.verification.every((v) => v.ok);
  const dims = c.dims.filter((d) => filter === "all" || d.source === filter);
  const counts = c.dims.reduce<Record<string, number>>((a, d) => ((a[d.source] = (a[d.source] ?? 0) + 1), a), {});

  return (
    <div className="body">
      <div className="viewport comp-viewport">
        <div className="comp-toolbar">
          {L > 0 && W > 0 && H > 0 && (
            <label><input type="checkbox" checked={showDims} onChange={(e) => setShowDims(e.target.checked)} /> Dimensions</label>
          )}
          <label><input type="checkbox" checked={wire} onChange={(e) => setWire(e.target.checked)} /> Wireframe</label>
          <label><input type="checkbox" checked={spin} onChange={(e) => setSpin(e.target.checked)} /> Turntable</label>
          {c.xray && (
            <label><input type="checkbox" checked={xray} onChange={(e) => setXray(e.target.checked)} /> X-ray</label>
          )}
          {operable && (
            <button
              className={`tick-toggle ${on ? "on" : ""}`}
              role="switch"
              aria-checked={on}
              onClick={() => setOn((v) => !v)}
            >
              <span className="tick-box">{on ? "✓" : ""}</span>{" "}
              {actuator ? (on ? "ON — pressed" : "OFF — released") : `${c.operate ?? "operate"}: ${on ? "ON" : "OFF"}`}
            </button>
          )}
          {isIr && (
            <label className="track-slider">
              track at x = {track.toFixed(0)} mm
              <input type="range" min={-8} max={38} step={0.5} value={track}
                onChange={(e) => setTrack(Number(e.target.value))} />
            </label>
          )}
          <span className="comp-hint">
            drag to orbit · scroll to zoom · click a sub-part{actuator ? " · click the red actuator to switch" : ""}
          </span>
        </div>
        <ErrorBoundary>
          <Canvas
            key={id}
            shadows
            dpr={[1, 2]}
            gl={{ preserveDrawingBuffer: true, toneMapping: THREE.ACESFilmicToneMapping }}
            camera={{ position: [-0.1, 0.07, 0.11], fov: 32, near: 0.001, far: 5 }}
            onPointerMissed={() => setPicked(null)}
          >
            {/* mid-grey studio backdrop: black ft housings vanish against near-black */}
            <color attach="background" args={["#2b3540"]} />
            <hemisphereLight args={["#e8eef4", "#1a2028", 0.55]} />
            {/* studio lighting baked from light panels - no network HDRI needed */}
            <Environment resolution={256}>
              <Lightformer intensity={3} position={[0, 3, 2]} scale={[6, 2, 1]} />
              <Lightformer intensity={1.8} position={[-4, 1, -1]} rotation-y={Math.PI / 2} scale={[4, 3, 1]} />
              <Lightformer intensity={1.4} position={[4, 0.5, 1]} rotation-y={-Math.PI / 2} scale={[3, 3, 1]} />
              <Lightformer intensity={2} position={[0, 1, -4]} scale={[6, 3, 1]} />
              <Lightformer form="ring" intensity={2} position={[1, 2, 4]} scale={1.5} />
            </Environment>
            <directionalLight position={[0.1, 0.2, 0.1]} intensity={1.4} castShadow shadow-mapSize={[2048, 2048]} />
            {/* rim light from behind, so dark edges separate from the backdrop */}
            <directionalLight position={[-0.05, 0.08, -0.15]} intensity={1.6} color="#cfe6ff" />
            <Suspense fallback={<Html center className="dim-label">loading {c.name}…</Html>}>
              <Bounds fit clip observe margin={1.5}>
                <group>
                  <Part url={`${BASE}${c.files.glb}`} picked={picked} onPick={setPicked} wire={wire}
                    actuator={actuator} pressed={on} onToggle={() => setOn((v) => !v)}
                    motion={motion} running={on} xray={xray} />
                  {isIr && (
                    // white card with a 10 mm black track, 15 mm in front of the windows
                    <group rotation={[-Math.PI / 2, 0, 0]} scale={0.001}>
                      <mesh position={[L / 2, -15, H / 2]} rotation={[Math.PI / 2, 0, 0]}>
                        <planeGeometry args={[60, 30]} />
                        <meshStandardMaterial color="#f4f4f0" side={THREE.DoubleSide} />
                      </mesh>
                      <mesh position={[track, -14.9, H / 2]} rotation={[Math.PI / 2, 0, 0]}>
                        <planeGeometry args={[10, 30]} />
                        <meshStandardMaterial color="#111" side={THREE.DoubleSide} />
                      </mesh>
                    </group>
                  )}
                  {showDims && L > 0 && W > 0 && H > 0 && (
                    // the part's own frame: mm, Z up -> same transform as the glb root
                    <group rotation={[-Math.PI / 2, 0, 0]} scale={0.001}>
                      <DimLine a={[0, 0, 0]} b={[L, 0, 0]} off={[0, -6, 0]} label={f(L)} />
                      <DimLine a={[L, 0, 0]} b={[L, W, 0]} off={[6, 0, 0]} label={f(W)} />
                      <DimLine a={[0, 0, 0]} b={[0, 0, H]} off={[-6, -6, 0]} label={f(H)} />
                      {id === "encoder_motor" && (
                        <DimLine a={[-g("shaft_l"), W / 2, H / 2 + g("shaft_d") / 2]} b={[0, W / 2, H / 2 + g("shaft_d") / 2]}
                          off={[0, 0, 8]} label={`shaft ${f(g("shaft_l"))} · Ø${g("shaft_d").toFixed(2)} · AF ${(g("shaft_d") - 2 * g("flat")).toFixed(2)}`} />
                      )}
                    </group>
                  )}
                </group>
              </Bounds>
            </Suspense>
            <ContactShadows position={[0, -0.0005, 0]} opacity={0.55} scale={0.3} blur={2.2} far={0.08} />
            <OrbitControls makeDefault enableDamping autoRotate={spin} autoRotateSpeed={1.2} />
          </Canvas>
        </ErrorBoundary>
      </div>

      <aside className="sidebar">
        <section className="panel">
          <h2>
            {c.name} <span className="tag idle">{c.kind === "mechanism" ? c.upgrade : `ft ${c.ft}`}</span>
          </h2>
          <p className="clock">{c.name_de} · {c.material}</p>
          <p className="clock">
            Built in FreeCAD by <code>{c.generator ?? "components_cad.py"}</code> · {c.mesh.triangles.toLocaleString()} triangles
            at {c.mesh.chordal_tolerance_mm} mm chordal tolerance · overall{" "}
            {c.overall_mm.map((v) => v.toFixed(2)).join(" × ")} mm
          </p>
          <p className="comp-files">
            <a href={`${BASE}${c.files.step}`} download>Download STEP</a>
            <span className="clock"> · FreeCAD: <code>{c.files.fcstd}</code></span>
          </p>
        </section>

        <section className="panel">
          <h2>
            Accuracy check <span className={`tag ${allOk ? "run" : "warn"}`}>{allOk ? "PASS" : "FAIL"}</span>
          </h2>
          <table className="tbl">
            <thead><tr><th>check</th><th className="num">spec</th><th className="num">model</th><th>source</th></tr></thead>
            <tbody>
              {c.verification.map((v) => (
                <tr key={v.check}>
                  <td>{v.check}</td>
                  <td className="num">{v.datasheet_mm.toFixed(2)}</td>
                  <td className={`num ${v.ok ? "" : "warn"}`}>{v.model_mm.toFixed(3)}</td>
                  <td><span className={`src src-${v.source ?? "datasheet"}`}>{SRC_LABEL[v.source ?? "datasheet"]}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="clock">
            Exact B-rep bounding box against the table, tolerance 0.01 mm. The model is only as
            true as its spec: a “measure” spec means the real part has not been measured yet.
          </p>
        </section>

        {actuator && <SwitchState on={on} onToggle={() => setOn((v) => !v)} />}
        {id === "solenoid_valve" && <ValveState on={on} onToggle={() => setOn((v) => !v)} />}
        {id === "compressor" && <PumpState on={on} />}
        {id === "pneumatic_cylinder" && <CylinderState on={on} />}
        {id === "s_motor" && <MotorState on={on} />}
        {isIr && <TrackState track={track} xs={[g("win_x"), L - g("win_x")]} r={g("win_d") / 2} />}

        <section className="panel">
          <h2>Selected sub-part</h2>
          {part ? (
            <table className="tbl"><tbody>
              <tr><th>name</th><td>{part.name}</td></tr>
              <tr><th>material</th><td>{part.material}</td></tr>
              <tr><th>envelope</th><td>{part.inside_envelope ? "inside the datasheet envelope" : "protrudes beyond it"}</td></tr>
            </tbody></table>
          ) : (
            <p className="clock">Click the model. Sub-parts: {c.parts.map((p) => p.name).join(", ")}</p>
          )}
        </section>

        <section className="panel">
          <h2>Ratings and function</h2>
          <table className="tbl"><tbody>
            {c.facts.map((x) => (
              <tr key={x.label}>
                <th>{x.label}</th><td>{x.value}</td>
                <td><span className={`src src-${x.source}`}>{SRC_LABEL[x.source]}</span></td>
              </tr>
            ))}
          </tbody></table>
          <p className="clock">Source: {c.datasheet}</p>
        </section>

        <section className="panel">
          <h2>Dimensions</h2>
          <div className="src-filter">
            {(["all", "datasheet", "model", "booklet", "photo", "ft-std", "assumed"] as const).filter((s) => s === "all" || counts[s]).map((s) => (
              <button key={s} className={filter === s ? "on" : ""} onClick={() => setFilter(s)}>
                {s === "all" ? `all ${c.dims.length}` : `${SRC_LABEL[s]} ${counts[s] ?? 0}`}
              </button>
            ))}
          </div>
          <table className="tbl">
            <tbody>
              {dims.map((d) => (
                <tr key={d.key} title={d.note || doc.sources[d.source]}>
                  <td>{d.label}</td>
                  <td className="num">{d.value.toFixed(2)}</td>
                  <td><span className={`src src-${d.source}`}>{SRC_LABEL[d.source]}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="clock">
            {c.kind === "mechanism"
              ? <>“model” values are the ones the factory's proofs run on; “measure” = an assumption of the model, to confirm on the real part.</>
              : <>Only “datasheet” values are authoritative. “measure” = not documented anywhere: confirm with calipers, change <code>components.py</code>, rebuild.</>}
          </p>
        </section>

        <section className="panel">
          <h2>Used in the factory <span className="tag idle">{c.used_in.length}×</span></h2>
          <table className="tbl">
            <thead><tr><th>module</th><th>part</th><th>I/O</th></tr></thead>
            <tbody>
              {c.used_in.map((u) => (
                <tr key={u.module + u.part} title={u.function}>
                  <td>{u.module}</td><td>{u.part}</td><td>{u.io}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      </aside>
    </div>
  );
}
